// Opt-out and re-subscribe gate for the outbound email queue.
//
// State lives in $STATE_DIR/suppression/<sha256 of canonical address>/, one
// small JSON file per event. Every worker reads and writes the same files, so
// any worker can record an event and any worker can enforce it, including
// after a restart. Each file is written to a temp name and renamed into place,
// so readers never see a half-written event.
//
// Decision rule: for each person, the event with the latest provider
// timestamp (`at`) wins. If two events share a timestamp, the unsubscribe wins.
// Arrival order does not matter, so a late "unsubscribe" that happened after a
// "re-subscribe" still blocks, and a late, older "re-subscribe" cannot undo a
// newer unsubscribe.
//
// Rules enforced by mayEmail:
// - Marketing mail stops once the latest event for the person is an unsubscribe.
//   CAN-SPAM (15 U.S.C. 7704) requires honoring an opt-out, and Gmail/Yahoo
//   bulk-sender rules expect the same, so we stop immediately rather than wait
//   for a grace period.
// - Transactional mail (order receipts, password resets) is never blocked by an
//   opt-out. The recipient expects it, and CAN-SPAM exempts it from opt-out.
// - If the store cannot be read, marketing mail is refused (fail closed).
//   Transactional mail does not depend on the store, so it still goes out.

import { createHash, randomUUID } from "node:crypto";
import { mkdir, readdir, readFile, rename, writeFile } from "node:fs/promises";
import { join } from "node:path";

const KIND_UNSUBSCRIBE = "unsubscribe";
const KIND_RESUBSCRIBE = "resubscribe";

function storeRoot() {
  const stateDir = process.env.STATE_DIR;
  if (!stateDir) throw new Error("STATE_DIR is not set");
  return join(stateDir, "suppression");
}

// Maps one address to the person behind it, so opt-outs cannot be dodged by
// case, display name, plus-tags, Gmail dots, or googlemail.com.
export function canonicalEmail(input) {
  if (typeof input !== "string") throw new TypeError("email must be a string");
  let s = input.trim();
  const angle = s.match(/<([^<>]+)>/); // "Name" <addr> as seen in a header
  if (angle) s = angle[1].trim();
  s = s.replace(/^mailto:/i, "").normalize("NFKC").toLowerCase();
  if (/\s/.test(s)) throw new TypeError("email contains whitespace");
  const at = s.lastIndexOf("@");
  if (at <= 0 || at === s.length - 1) throw new TypeError("email has no local part or domain");
  let local = s.slice(0, at);
  let domain = s.slice(at + 1);
  local = local.split("+")[0]; // a+news@x and a@x are the same mailbox
  if (local === "") throw new TypeError("email has an empty local part");
  if (domain === "googlemail.com") domain = "gmail.com";
  if (domain === "gmail.com") local = local.replace(/\./g, ""); // Gmail ignores dots
  return `${local}@${domain}`;
}

function toMillis(at) {
  if (!(at instanceof Date) || Number.isNaN(at.getTime())) {
    throw new TypeError("at must be a valid Date");
  }
  return at.getTime();
}

function keyDir(canon) {
  return join(storeRoot(), createHash("sha256").update(canon).digest("hex"));
}

async function writeEvent(kind, email, at) {
  const canon = canonicalEmail(email);
  const ms = toMillis(at);
  const dir = keyDir(canon);
  await mkdir(dir, { recursive: true });

  // The file name depends only on the event content, so a duplicate delivery
  // of the same webhook overwrites the file with identical bytes.
  const finalPath = join(dir, `${ms}-${kind}.json`);
  const tmpPath = join(dir, `.${ms}-${kind}.${process.pid}.${randomUUID()}.tmp`);
  const body = JSON.stringify({ email: canon, kind, at: ms });
  await writeFile(tmpPath, body);
  await rename(tmpPath, finalPath);
}

function isLater(candidate, current) {
  if (candidate.at !== current.at) return candidate.at > current.at;
  return candidate.kind === KIND_UNSUBSCRIBE && current.kind !== KIND_UNSUBSCRIBE;
}

// Returns the winning event for an address, or null if there are none.
async function currentDecision(canon) {
  const dir = keyDir(canon);
  let names;
  try {
    names = await readdir(dir);
  } catch (err) {
    if (err.code === "ENOENT") return null;
    throw err;
  }
  let best = null;
  for (const name of names) {
    if (!name.endsWith(".json") || name.startsWith(".")) continue;
    const event = JSON.parse(await readFile(join(dir, name), "utf8"));
    if (!best || isLater(event, best)) best = event;
  }
  return best;
}

export async function recordUnsubscribe(email, at) {
  await writeEvent(KIND_UNSUBSCRIBE, email, at);
}

export async function recordResubscribe(email, at) {
  await writeEvent(KIND_RESUBSCRIBE, email, at);
}

// `now` is accepted for the queue's API. The decision depends only on event
// timestamps, so an unsubscribe that is already stored blocks mail even when
// it was queued before the unsubscribe happened.
export async function mayEmail(message, now) {
  const deny = (reason) => ({ allowed: false, reason });
  const allow = () => ({ allowed: true, reason: null });

  if (!message || typeof message !== "object") return deny("invalid_message");
  if (message.kind === "transactional") return allow();
  if (message.kind !== "marketing") return deny("unknown_kind");

  let canon;
  try {
    canon = canonicalEmail(message.to);
  } catch {
    return deny("invalid_recipient");
  }

  let decision;
  try {
    decision = await currentDecision(canon);
  } catch {
    return deny("suppression_check_failed");
  }
  if (decision && decision.kind === KIND_UNSUBSCRIBE) return deny("unsubscribed");
  return allow();
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  canonicalEmail,
  mayEmail,
  recordResubscribe,
  recordUnsubscribe,
} from "./bot.mjs";

const marketing = (to) => ({ to, kind: "marketing" });
const transactional = (to) => ({ to, kind: "transactional" });
const t = (n) => new Date(1_700_000_000_000 + n);

let dir;
test.beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "bot-test-"));
  process.env.STATE_DIR = join(dir, "not-yet-created"); // must be created on demand
});
test.afterEach(async () => {
  await rm(dir, { recursive: true, force: true });
  delete process.env.STATE_DIR;
});

test("canonicalEmail folds case, display names, plus-tags, Gmail dots", () => {
  const a = canonicalEmail("<EMAIL>");
  assert.equal(a, "<EMAIL>");
  assert.equal(canonicalEmail('"Jane" <<EMAIL>>'), a);
  assert.equal(canonicalEmail("mailto:<EMAIL>"), a);
  assert.equal(canonicalEmail("  x+tag@Example.COM "), "x@example.com");
});

test("canonicalEmail rejects malformed input", () => {
  for (const bad of ["", "no-at-sign", "@x.com", "a@", "<EMAIL>", "a <EMAIL>", 5]) {
    assert.throws(() => canonicalEmail(bad), TypeError, String(bad));
  }
});

test("unsubscribe blocks marketing, not transactional", async () => {
  await recordUnsubscribe("<EMAIL>", t(1));
  assert.deepEqual(await mayEmail(marketing("<EMAIL>"), t(2)), { allowed: false, reason: "unsubscribed" });
  assert.deepEqual(await mayEmail(transactional("<EMAIL>"), t(2)), { allowed: true, reason: null });
});

test("unsubscribe applies to every spelling of the same person", async () => {
  await recordUnsubscribe('"A" <<EMAIL>>', t(1));
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(2))).reason, "unsubscribed");
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(2))).reason, "unsubscribed");
});

test("an unrelated address is not blocked", async () => {
  await recordUnsubscribe("<EMAIL>", t(1));
  assert.deepEqual(await mayEmail(marketing("<EMAIL>"), t(2)), { allowed: true, reason: null });
});

test("no events means marketing is allowed", async () => {
  assert.deepEqual(await mayEmail(marketing("<EMAIL>"), t(0)), { allowed: true, reason: null });
});

test("resubscribe after unsubscribe re-enables marketing", async () => {
  await recordUnsubscribe("<EMAIL>", t(1));
  await recordResubscribe("<EMAIL>", t(2));
  assert.deepEqual(await mayEmail(marketing("<EMAIL>"), t(3)), { allowed: true, reason: null });
});

test("out of order: a late older resubscribe does not undo a newer unsubscribe", async () => {
  await recordUnsubscribe("<EMAIL>", t(5));
  await recordResubscribe("<EMAIL>", t(2)); // arrives late
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(6))).reason, "unsubscribed");
});

test("out of order: a late unsubscribe does not undo a newer resubscribe", async () => {
  await recordResubscribe("<EMAIL>", t(5));
  await recordUnsubscribe("<EMAIL>", t(2)); // arrives late
  assert.deepEqual(await mayEmail(marketing("<EMAIL>"), t(6)), { allowed: true, reason: null });
});

test("same timestamp: unsubscribe wins regardless of arrival order", async () => {
  await recordResubscribe("<EMAIL>", t(3));
  await recordUnsubscribe("<EMAIL>", t(3));
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(4))).reason, "unsubscribed");

  await recordUnsubscribe("<EMAIL>", t(3));
  await recordResubscribe("<EMAIL>", t(3));
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(4))).reason, "unsubscribed");
});

test("duplicate webhook deliveries are harmless", async () => {
  for (let i = 0; i < 3; i++) await recordUnsubscribe("<EMAIL>", t(1));
  await recordResubscribe("<EMAIL>", t(2));
  for (let i = 0; i < 3; i++) await recordUnsubscribe("<EMAIL>", t(1)); // old, replayed
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(3))).allowed, true);
});

test("concurrent writes from many workers are all kept", async () => {
  const people = Array.from({ length: 50 }, (_, i) => `p${i}@x.com`);
  await Promise.all(people.flatMap((p) => [recordUnsubscribe(p, t(1)), recordUnsubscribe(p, t(1))]));
  const results = await Promise.all(people.map((p) => mayEmail(marketing(p), t(2))));
  assert.ok(results.every((r) => r.reason === "unsubscribed"));
});

test("state survives a restart (fresh module instance reads the same files)", async () => {
  await recordUnsubscribe("<EMAIL>", t(1));
  const fresh = await import(`./bot.mjs?restart=${Date.now()}`);
  assert.equal((await fresh.mayEmail(marketing("<EMAIL>"), t(2))).reason, "unsubscribed");
});

test("invalid input is refused, never allowed", async () => {
  assert.equal((await mayEmail(marketing("nope"), t(0))).reason, "invalid_recipient");
  assert.equal((await mayEmail(null, t(0))).reason, "invalid_message");
  assert.equal((await mayEmail({ to: "<EMAIL>", kind: "promo" }, t(0))).reason, "unknown_kind");
});

test("marketing fails closed when the store is unavailable; transactional still goes", async () => {
  delete process.env.STATE_DIR;
  assert.equal((await mayEmail(marketing("<EMAIL>"), t(0))).reason, "suppression_check_failed");
  assert.deepEqual(await mayEmail(transactional("<EMAIL>"), t(0)), { allowed: true, reason: null });
});

test("invalid event input throws instead of being stored", async () => {
  await assert.rejects(recordUnsubscribe("<EMAIL>", "2026-01-01"), TypeError);
  await assert.rejects(recordUnsubscribe("bad", t(1)), TypeError);
});
